function FR.worth(m)
    local hp = tonumber(m:GetAttribute("HP")); if not hp then return true end
    local now = Workspace:GetServerTimeNow()
    local left = (tonumber(m:GetAttribute("ExpiresAt")) or (now + 120)) - now
    local log = FR.hp[m.Name]
    if not log then log = { t = os.clock(), hp = hp }; FR.hp[m.Name] = log end
    local dt = os.clock() - log.t
    local rate = dt > 2 and math.max(0, (log.hp - hp) / dt) or 0
    local d = G.data()
    local mine = (tonumber(d and d.Strength) or 1) / 0.15
    local eta = hp / math.max(1, rate + (S.task == "Meteor" and 0 or mine))
    FR.eta, FR.left = eta, left
    if on("ev_always") then return left > 0 end
    return eta <= left + 3
end
function FR.events()
    if not on("ev_auto") or S.busy then return end
    local live = Workspace:FindFirstChild("Live"); if not live then return end
    local home = P.home()
    local coins = live:FindFirstChild("BloodMoonCoins")
    for _, c in ipairs(coins and coins:GetChildren() or {}) do
        local p = posOf(c)
        if p and G.R:FindFirstChild("BloodMoon: Pickup Coin") then S.busy = true; tp(p); task.wait(0.15); fire("BloodMoon: Pickup Coin", c.Name); S.busy = false end
    end
    local sc = live:FindFirstChild("SummerCoins")
    for _, c in ipairs(sc and sc:GetChildren() or {}) do
        local p = posOf(c)
        if p then S.busy = true; tp(p); task.wait(0.15); fire("Summer: Pickup Coin", c.Name); S.busy = false end
    end
    local m = FR.meteor()
    if m and not attr("holdingFriend") and FR.worth(m) then
        S.busy = true; S.task = "Meteor"
        local mp = posOf(m)
        local egg = mp and FR.encased(mp)
        local spot = FR.spot(m)
        if spot then tp(spot) end
        local t0 = os.clock()
        local tick = 0
        while RUNNING and on("ev_auto") and os.clock() - t0 < 900 do
            if egg and egg.Parent and not egg:GetAttribute("MeteorEncased") then FR.grab(egg); break end
            if not m.Parent then
                local e2 = egg or (mp and FR.encased(mp))
                if e2 and e2.Parent then
                    local t1 = os.clock()
                    while e2:GetAttribute("MeteorEncased") and os.clock() - t1 < 2 do task.wait(0.03) end
                    FR.grab(e2)
                end
                break
            end
            mp = posOf(m) or mp
            egg = egg or (mp and FR.encased(mp))
            local r = hrp()
            if spot and r and (r.Position - spot).Magnitude > 10 then tp(spot) end
            fire("Bloodlit Meteor Drill", m.Name)
            tick = tick + 1
            if tick % 40 == 0 and not FR.worth(m) then break end
            task.wait(0.15)
        end
        S.busy = false
        local h = P.home(); if h and not attr("holdingFriend") then tp(h) end
    end
    if home and (coins or sc) and hrp() and (hrp().Position - home).Magnitude > 60 and not S.busy then tp(home) end
end
local WD = {}
function WD.bright(v)
    if v then
        WD.saved = WD.saved or { Lighting.Brightness, Lighting.ClockTime, Lighting.GlobalShadows, Lighting.Ambient }
        Lighting.Brightness = 2; Lighting.ClockTime = 14; Lighting.GlobalShadows = false; Lighting.Ambient = Color3.fromRGB(180, 180, 180)
    elseif WD.saved then
        Lighting.Brightness, Lighting.ClockTime, Lighting.GlobalShadows, Lighting.Ambient = table.unpack(WD.saved)
        WD.saved = nil
    end
end
function WD.gfx(v)
    if v then WD.gfxOn = true elseif not WD.gfxOn then return end
    pcall(function() settings().Rendering.QualityLevel = v and Enum.QualityLevel.Level01 or Enum.QualityLevel.Automatic end)
    for _, d in ipairs(Workspace:GetDescendants()) do
        if d:IsA("ParticleEmitter") or d:IsA("Trail") or d:IsA("Beam") then pcall(function() d.Enabled = not v end) end
    end
    if not v then WD.gfxOn = nil end
end
