track(RunService.Stepped:Connect(function()
    if not RUNNING then return end
    local c = char(); if not c then return end
    if on("mv_noclip") then for _, p in ipairs(c:GetDescendants()) do if p:IsA("BasePart") and p.CanCollide then p.CanCollide = false end end end
    local h = hum()
    if h and on("mv_speed") then h.WalkSpeed = val("mv_speed_v", 60) end
    local r = hrp()
    if r and on("mv_fly") and not S.busy then
        local cam = Workspace.CurrentCamera
        local dir = Vector3.zero
        if UserInputService:IsKeyDown(Enum.KeyCode.W) then dir = dir + cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.S) then dir = dir - cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.D) then dir = dir + cam.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.A) then dir = dir - cam.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then dir = dir + Vector3.yAxis end
        if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then dir = dir - Vector3.yAxis end
        if h and h.MoveDirection.Magnitude > 0 and dir.Magnitude == 0 then dir = h.MoveDirection end
        r.AssemblyLinearVelocity = (dir.Magnitude > 0 and dir.Unit or Vector3.zero) * val("mv_fly_v", 60)
    end
end))
