task.spawn(function()
    while RUNNING do
        if getgenv().Library ~= Library then getgenv().Library = Library end
        local d = G.data()
        if d then
            local used, inc = 0, 0
            for _, p in pairs(d.PlotFriends or {}) do used = used + 1; if p.incubating then inc = inc + 1 end end
            setText(UI.status, os.clock() - S.msgAt < 4 and S.msg or S.task)
            setText(UI.stats1, string.format(L["%d eggs · %d lost"], S.eggs, S.lost))
            setText(UI.stats2, string.format(L["%d/%d slots · %d hatching"], used, P.slots(d), inc))
            local nxt = G.DB.Rebirths and G.DB.Rebirths[(tonumber(d.Rebirth) or 0) + 1]
            setText(UI.stats3, string.format(L["%s power · %s"], short(d.Strength), (tostring((G.DB.Dumbells and G.DB.Dumbells[d.EquippedDumbell or ""] or {}).Name or "?"):gsub(" Drill$", ""))))
            local pw = tonumber(d.Strength) or 0
            if S.pwT and pw >= (S.pwV or 0) and os.clock() - S.pwT >= 5 then S.pRate = (pw - S.pwV) / (os.clock() - S.pwT); S.pwT, S.pwV = os.clock(), pw
            elseif not S.pwT or pw < (S.pwV or 0) then S.pwT, S.pwV = os.clock(), pw end
            if not nxt then setText(UI.stats5, L["Max rebirth"])
            elseif pw >= (tonumber(nxt.StrengthRequirement) or math.huge) then setText(UI.stats5, string.format(L["Rebirth ready · x%s"], tostring(nxt.CashMulti)))
            else
                local need = (tonumber(nxt.StrengthRequirement) or 0) - pw
                setText(UI.stats5, string.format(L["Rebirth %d at %s%s"], (tonumber(d.Rebirth) or 0) + 1, short(nxt.StrengthRequirement), (S.pRate or 0) > 0 and (" · " .. dur(need / S.pRate)) or ""))
            end
            local mm = FR.meteor()
            if mm then
                local rr = tostring(mm:GetAttribute("EggRarity") or "")
                if S.task == "Meteor" then setText(UI.stats6, string.format(L["Mining %s egg · %s"], rr, (FR.eta or 0) > (FR.left or 0) and L["won't crack"] or dur(FR.eta or 0)))
                else setText(UI.stats6, string.format(L["%s meteor too strong"], rr)) end
            else
                setText(UI.stats6, string.format(L["%d meteor eggs"], S.meteors or 0))
            end
            local z = W.next()
            local secs = z and W.need(z, d)
            setText(UI.stats4, z and string.format(L["Next: %s · %s"], z, dur(secs)) or L["All floors open"])
            local fs
            if not z then fs = L["Done"]
            elseif not on("fl_auto") then fs = L["Off"]
            elseif W.state == "drill" then fs = L["Drilling · "] .. dur(math.max(0, (W.ends or 0) - os.clock())) .. L[" left"]
            elseif (secs or 0) > val("fl_max", 10) * 60 then fs = L["Waiting for power"]
            else fs = L["Starting…"] end
            setText(UI.stats7, fs)
        end
        task.wait(0.5)
    end
end)
pcall(function() SaveManager:LoadAutoloadConfig() end)
notify(L["Loaded"])

end
